// Demo-Antworten ohne KI: testet Verbindung, Button, Animation und Links – kostenlos
const b = $json.body || {};
const msgs = Array.isArray(b.messages) ? b.messages : [];
const last = msgs.filter(m => m && m.role === 'user').pop();
const q = String(last && last.content || '').toLowerCase();
const demo = '\n\n(Demo-Modus: Diese Antwort kommt aus dem Test-Workflow, nicht von der KI.)';
let reply;
if (!q) {
  reply = 'Ich habe keine Frage erhalten. Bitte schreiben Sie etwas in das Eingabefeld.';
} else if (q.includes('bewerbung')) {
  reply = 'Für eine Bewerbung reicht meist die **Gratis-Version** eines Chat-Assistenten.\n\n- Keine Adresse oder Geburtsdatum eingeben\n- Erfundene Qualifikationen streichen\n\nVorlagen finden Sie im [[aufgaben]].';
} else if (q.includes('saas') || q.includes('paas') || q.includes('iaas') || q.includes('cloud')) {
  reply = 'Ob SaaS, PaaS oder IaaS passt, hängt vor allem von Schutzbedarf, Anpassungsbedarf und eigener IT-Kompetenz ab. Für einen internen Wissensassistenten mit eigenen Dokumenten ist oft **PaaS mit RAG** sinnvoll.\n\nPrüfen Sie Ihr Vorhaben in der [[entscheid]].';
} else if (q.includes('abo') || q.includes('kosten') || q.includes('preis')) {
  reply = 'Bei seltener Nutzung reicht die Gratis-Version. Ab täglicher Nutzung oder für lange Dokumente lohnt sich meist ein Abo um rund 20 € im Monat.\n\nMehr dazu unter [[privat]] und im [[rechner]].';
} else if (q.includes('training') || q.includes('datenschutz') || q.includes('chatgpt')) {
  reply = 'Bei ChatGPT schalten Sie unter Einstellungen → Datenkontrollen die Option „Das Modell für alle verbessern“ aus.\n\nEinen Überblick über alle Dienste gibt die [[ampel]].';
} else if (q.includes('fehler')) {
  // Zum Testen der Fehleranzeige: Frage mit dem Wort „Fehler“ senden
  return [{ json: { reply: '' } }];
} else {
  reply = 'Danke für Ihre Frage: „' + String(last.content).slice(0, 120) + '“. Die Verbindung zum Chat-Endpunkt funktioniert.\n\nTesten Sie auch die Beispielfragen oder schauen Sie ins [[glossar]].';
}
return [{ json: { reply: reply + demo } }];
